import numpy as np

def make_prices(n=750, seed=21, mu=0.0003, sigma=0.012):
    """n + 1 daily closes from 100: daily log returns mu + sigma * noise."""
    rng = np.random.default_rng(seed)
    r = mu + sigma * rng.standard_normal(n)
    return np.round(100 * np.exp(np.concatenate([[0.0], np.cumsum(r)])), 4).tolist()

def make_regime_prices(n=500, seed=11, calm=0.006, wild=0.02):
    """n + 1 closes: calm for the first half, wild for the second."""
    rng = np.random.default_rng(seed)
    sig = np.where(np.arange(n) < n // 2, calm, wild)
    r = 0.0002 + sig * rng.standard_normal(n)
    return np.round(100 * np.exp(np.concatenate([[0.0], np.cumsum(r)])), 4).tolist()

def log_returns(prices):
    """Daily log returns: entry t is ln(P[t+1] / P[t])."""
    p = np.asarray(prices, dtype=float)
    return np.round(np.diff(np.log(p)), 8).tolist()

def rolling_vol(prices, window=20):
    """vol[t]: sample sd of the last `window` simple returns ending on day t (nan before)."""
    p = np.asarray(prices, dtype=float)
    r = p[1:] / p[:-1] - 1
    vol = [float('nan')] * len(p)
    for t in range(window, len(p)):
        vol[t] = float(np.std(r[t - window:t], ddof=1))
    return vol

def make_trend_prices(n=1500, seed=20, block=60):
    """n + 1 closes in 60-day blocks: half trend (drift 0.3% a day either way, vol 0.8%),
    half chop (no drift, vol 1.6%)."""
    rng = np.random.default_rng(seed)
    r = []
    while len(r) < n:
        if rng.random() < 0.5:
            r += list(rng.choice([-1, 1]) * 0.003 + 0.008 * rng.standard_normal(block))
        else:
            r += list(0.016 * rng.standard_normal(block))
    r = np.array(r[:n])
    return np.round(100 * np.exp(np.concatenate([[0.0], np.cumsum(r)])), 4).tolist()

def _touch(path, upper, lower, h):
    for d in range(1, min(h, len(path) - 1) + 1):
        if path[d] <= lower:
            return (-1, d)
        if path[d] >= upper:
            return (1, d)
    return (0, min(h, len(path) - 1))

def tb_events(prices, vol, k, h, start):
    """(label, days to touch) for entries start .. len(prices) - h - 1."""
    return [_touch(prices[t:t + h + 1], prices[t] * (1 + k * vol[t]),
                   prices[t] * (1 - k * vol[t]), h) for t in range(start, len(prices) - h)]

def _side(prices, fast, slow):
    p = np.asarray(prices, dtype=float)
    return [1 if p[t - fast + 1:t + 1].mean() > p[t - slow + 1:t + 1].mean() else -1
            for t in range(slow - 1, len(p))]

def meta_dataset(seed=20, k=2.5, h=10):
    """Crossover (5, 20) sides on make_trend_prices(1500, seed), triple-barrier outcomes
    (k, h), meta-labels, and two features per event: 20-day vol (%) and the 10-day
    return in the direction of the side (%). Events are days 20 to len - h - 1."""
    p = make_trend_prices(1500, seed)
    vol = rolling_vol(p, 20)
    P = np.asarray(p)
    side = _side(p, 5, 20)
    X, y = [], []
    for t in range(20, len(p) - h):
        s = side[t - 19]
        lab = _touch(p[t:t + h + 1], p[t] * (1 + k * vol[t]), p[t] * (1 - k * vol[t]), h)[0]
        X.append([round(vol[t] * 100, 4), round((P[t] / P[t - 10] - 1) * 100 * s, 4)])
        y.append(1 if s * lab == 1 else 0)
    return np.array(X), y

